#pragma once
/*
 * LB_TFTInitExtra.h - init tables that are NOT captured from Arduino_GFX.
 *
 * LB_TFTInit.h is generated by tools/gen_init.py from what Arduino_GFX's
 * drivers send. A controller Arduino_GFX has no driver for cannot be captured,
 * so its table is written here by hand, from a named source. Same format:
 *
 *   cmd, nbytes, delay_ms, data...   terminated by 0xFF, 0xFF.
 */
#include <stdint.h>

/* ILI9327 (240 x 432 RAM): MCUFRIEND_kbv's ILI9327_regValues, wrapped in its
 * reset_off / wake_on sequences - display off, RGB565, the table, sleep out
 * (150 ms), display on. The protection register B0 is left open, as there. */
static const uint8_t LB_INITSEQ_ILI9327[] = {
  0x28,0x00,0x00,
  0x3A,0x01,0x00,0x55,
  0xB0,0x01,0x00,0x00,
  0xC1,0x04,0x00,0x10,0x10,0x02,0x02,
  0xC0,0x06,0x00,0x00,0x35,0x00,0x00,0x01,0x02,
  0xC5,0x01,0x00,0x04,
  0xD2,0x02,0x00,0x01,0x04,
  0xCA,0x01,0x00,0x00,
  0xEA,0x01,0x00,0x80,
  0x11,0x00,0x96,
  0x29,0x00,0x00,
  0xFF,0xFF,
};

/* ILI9486 over SPI, 18-bit colour: Arduino_GFX's Arduino_ILI9486_18bit
 * (ili9486_18bit_init_operations). Sleep out first, 150 ms, COLMOD 0x66,
 * power control, gamma, display on, 25 ms. */
static const uint8_t LB_INITSEQ_ILI9486[] = {
  0x11,0x00,0x96,
  0x3A,0x01,0x00,0x66,
  0xC2,0x01,0x00,0x44,
  0xC5,0x04,0x00,0x00,0x00,0x00,0x00,
  0xE0,0x0F,0x00,0x0F,0x1F,0x1C,0x0C,0x0F,0x08,0x48,0x98,0x37,0x0A,0x13,0x04,0x11,0x0D,0x00,
  0xE1,0x0F,0x00,0x0F,0x32,0x2E,0x0B,0x0D,0x05,0x47,0x75,0x37,0x06,0x10,0x03,0x24,0x20,0x00,
  0x29,0x00,0x19,
  0xFF,0xFF,
};
